#!/usr/bin/env python3
import json,math,random,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];BASE=ROOT/'artifacts/rl-campaign/surveyor/15-field-cluster-rerun';reports=[json.loads((BASE/f'seed-{s}/report.json').read_text()) for s in (7319,7320,7321)]
final=[r['curve'][-1]['evaluation'] for r in reports];rates=[x['success_rate'] for x in final];success=sum(sum(y['success'] for y in x['rows']) for x in final);n=sum(len(x['rows']) for x in final);z=1.959963984540054;p=success/n;den=1+z*z/n;wilson=[(p+z*z/(2*n)-z*math.sqrt(p*(1-p)/n+z*z/(4*n*n)))/den,(p+z*z/(2*n)+z*math.sqrt(p*(1-p)/n+z*z/(4*n*n)))/den];rng=random.Random(7319);boots=[statistics.median(rng.choices(rates,k=len(rates))) for _ in range(10000)]
out={'schema_version':1,'artifact_kind':'15-field-cluster-recurrent-ppo-summary','status':'complete','host_class':'cluster','contract_sha256':reports[0]['contract_sha256'],'per_seed':[{'seed':r['training']['seed'],'curve':r['curve']} for r in reports],'final_success_rate_median_across_training_seeds':statistics.median(rates),'training_seed_bootstrap_95_ci':[sorted(boots)[249],sorted(boots)[9749]],'pooled_episode_success_rate':p,'pooled_wilson_95_ci':wilson,'hierarchy_warning':'The pooled Wilson interval treats evaluation episodes as exchangeable and does not model the training-seed hierarchy; the per-seed rates and training-seed bootstrap are primary.','preregistered_prediction_passed':statistics.median(rates)>=.56}
